@Override public void onError(WebSocket webSocket,Throwable t){
  try {
    logger.debug("{}: Throwable received from websocket",LOG_PREFIX,t);
    if (alive.get()) {
      serverThrowables.add(t);
      closeForwarder();
    }
  } catch (UnsupportedOperationException e) {
    logger.warn("Failed to add throwable to serverThrowables", e);
  } catch (SecurityException e) {
    logger.warn("Security exception while closing forwarder", e);
  }
}
